# Carols, hymns, spirituals and anthems: traditional or long out of copyright, in our own
# arrangements. Short form: see catalogue.M.
from catalogue import tune

tune('amazing-grace', 'Amazing Grace', 'Hymn tune "New Britain", America, 1829; words by John Newton, 1779', 'G', '3/4', 76,
     'D4:q | G:h B:e G | B:h A:q | G:h E:q | D:h D:q | G:h B:e G | B:h A:q | D5:h B4:q | D5:h B:e G | B:h A:q | G:h E:q | D:h D:q | G:h B:e G | B:h A:q | G:h',
     '- | G | G | C | G | G | G D | G | G | G D | C | G | G | D | G', 3, 'hymns', pickup='q',
     story='John Newton, a former slave-ship captain who became a priest, wrote the words. The tune "New Britain" came from American folk hymn books of the 1820s.',
     tips='Three slow beats. The eighth notes ("maz-ing") are a little turn: keep them smooth.')

tune('old-hundredth', 'Old Hundredth', 'Hymn tune by Louis Bourgeois, Geneva, 1551', 'G', '4/4', 80,
     'G4:h G:q F# | E:q D G A | B:h r:q B | B:q B A G | C5:q B4 A:h | r:q G A B | A:q G E F# | G:h r:q D5 | B4:q G A C5 | B4:q A G:h',
     'G | C D | G | G | C D | G | Am D | G | G Am | D G', 3, 'hymns',
     story='One of the oldest hymn tunes still sung, from the Genevan Psalter of 1551. In English churches it carries the words "Praise God, from whom all blessings flow".',
     tips='Every line starts and ends with a long note; the notes between walk by step.')

tune('first-noel', 'The First Noel', 'English carol, printed 1823', 'D', '3/4', 96,
     'F#4:e E | D:q. E:e F# G | A:h B:e C#5 | D5:q C# B | A:h B:e C# | D5:q C# B | A:q B C# | D5:q A4 G | F#:h F#:e E | D:q. E:e F# G | A:h B:e C# | D5:q C# B | A:h B:e C# | D5:q C# B | A:q B C# | D5:q A4 G | F#:h F#:e E | D:q. E:e F# G | A:h D5:e C# | B:h B:q | A:h. | D5:q C# B | A:q B C# | D5:q A4 G | F#:h',
     '- | D | D | G | D | G | D | G A | D | D | D | G | D | G | D | G A | D | D | D A | G | D | G | D | G A | D', 4, 'carols', pickup='e e',
     story='A Cornish carol, first printed in 1823. The tune climbs the scale from D to D again and again, like a peal of bells.',
     tips='D major: F♯ and C♯. The chorus ("No-el, No-el") starts in bar 17.')

tune('angels-we-have-heard', 'Angels We Have Heard on High', 'French carol "Les Anges dans nos campagnes", 1700s', 'F', '4/4', 96,
     'A4:q A A C5 | C:q. B:e A:h | A:q G A C5 | A:q. G:e F:h | A:q A A C5 | C:q. B:e A:h | A:q G A C5 | A:q. G:e F:h | C5:h D:e C B A | B:h C5:e B A G | A:h B:e A G F | G:h. C4:q | F:q G A B | A:h G:h | F:w',
     'F | C F | F | C F | F | C F | F | C F | F | Bb | Dm | C | F | C | F', 3, 'carols',
     story='The long "Glo-o-o-o-ria" in the chorus falls in a chain of little runs, each one step lower: a sequence.',
     tips='F major: B♭. The chorus runs are eighths: let them ring out evenly.')

tune('we-three-kings', 'We Three Kings', 'John Henry Hopkins Jr., 1857', 'Em', '6/8', 52,
     'B4:q A:e G:q E:e | F#:e G F# E:q. | B4:q A:e G:q E:e | F#:e G F# E:q. | G:q G:e A:q A:e | B:q B:e D5:e C B4 | A:e B A G:q F#:e | E:q. r:q.',
     'Em | B7 Em | Em | B7 Em | G D | G | Am B7 | Em', 7, 'carols',
     story='Written for a Christmas pageant in New York in 1857. The swaying 6/8 is the camels walking.',
     tips='E minor: F♯. Two big beats in each bar, a long-short swing.')

tune('ding-dong-merrily', 'Ding Dong Merrily on High', 'French dance tune "Branle de l\'Official", 1589', 'G', '4/4', 100,
     'G4:q G A:e G F# E | D:h D:h | E:q G G F# | G:h G:h | G4:q G A:e G F# E | D:h D:h | E:q G G F# | G:h G:h | D5:q. C:e B C D B | C:q. B:e A B C A | B4:q. A:e G A B G | A:q. G:e F# G A F# | G:h D4:q D | E:q G G F# | G:w',
     'G | D | C D | G | G | D | C D | G | G | Am | G | D | G | C D | G', 4, 'carols',
     story='The tune was a dance in a French book of 1589. The long "Gloria" falls like bells pealing down a tower.',
     tips='The chorus is a sequence: the same little run, a step lower each bar.')

tune('good-king-wenceslas', 'Good King Wenceslas', 'Spring carol "Tempus adest floridum", Piae Cantiones, 1582', 'G', '4/4', 96,
     'G4:q G G A | G G D:h | E:q D E F# | G:h G:h | G:q G G A | G G D:h | E:q D E F# | G:h G:h | D5:q C B A | B A G:h | E:q D E F# | G:h G:h | D:q D E F# | G G A:h | D5:q C B A | G:h C5:h | G4:w',
     'G | G D | C D | G | G | G D | C D | G | G D | G | C D | G | D | G D | G D | G C | G', 2, 'carols',
     story='The tune was a spring song printed in Finland in 1582; the words about the good king of Bohemia were added in 1853.',
     tips='All quarters and halves. G major: F♯ in bars 3 and 7.')

tune('god-save-the-king', 'God Save the King', 'British anthem, printed 1745', 'G', '3/4', 84,
     'G4:q G A | F#:q. G:e A:q | B:q B C5 | B4:q. A:e G:q | A:q G F# | G:h. | D5:q D D | D:q. C:e B4:q | C5:q C C | C:q. B4:e A:q | B4:q C5:e B4 A G | B:q. C5:e D5:q | E5:e C5 B4:q A | G:h.',
     'G | D | G | G | D | G | G | G | C | D7 | G | G | C D | G', 3, 'anthems',
     story='The British national anthem since the 1740s. Its tune is also the anthem of Liechtenstein and was once used in many other countries.',
     tips='Three steady beats, with a dotted rhythm (long-short) in bars 2, 4, 8, 10 and 12.')

tune('star-spangled-banner', 'The Star-Spangled Banner', 'United States anthem, tune "To Anacreon in Heaven" by John Stafford Smith, 1770s', 'C', '3/4', 84,
     'G4:e. E:s | C4:q E G | C5:h E5:e. D:s | C5:q E4 F# | G:h G:e G | E5:q. D:e C5:q | B4:h A:e B | C5:q C G4 | E:q C G4:e. E:s | C4:q E G | C5:h E5:e. D:s | C5:q E4 F# | G:h G:e G | E5:q. D:e C5:q | B4:h A:e B | C5:q C G4 | E:q C',
     '- | C | C | C D7 | G | C | G | C | C | C | C | C D7 | G | C | G | C | C', 5, 'anthems', pickup='e. s',
     story='The tune was an English club song of the 1770s. Francis Scott Key wrote the words to it in 1814; it became the American anthem in 1931.',
     tips='Wide leaps up and down the C chord. The dotted eighth and sixteenth is a quick "snap".')
